package com.jala.operators;

public class Q6_RelationalOperators {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=20;
		int b=30;
		int c=30;
		if(a>b) {
			System.out.println("A is bigger than B");
		}
		if(a<b) {
			System.out.println("B is bigger than A");			
		}
		if(b<=c) {
			System.out.println("B is Equal or Lesser than C");
		}
		if(b>=c) {
			System.out.println("B is Equal or Larger than C");
		}
	}

}
